"""Standalone executor for instruction-selected SSA target text.

This is *test support* for the execution-level pass-order regression suite
in ``test_pass_order_execution.py``.  It is **not** part of the compiler
package and adds no production dependency: it is plain standard-library
Python, invoked as a real operating-system process by the suite.

Why this exists
---------------
The language has no native code emitter; instruction selection is the
deterministic :func:`compiler_ir.render_module` plain-text emission, which
is the compiler's final stage.  The execution suite must therefore:

1. compile one legal source AST through the existing public entry points
   (``lower_module`` -> a legal permutation of ``to_ssa`` /
   ``fold_constants`` / ``eliminate_dead_code`` -> ``render_module``);
2. write the rendered text to its own temporary target file;
3. *execute* that artifact in an isolated OS process and capture the real
   process exit status, standard output and standard error.

This module parses **only** the rendered SSA text (the only kind produced
by the legal schedules in the execution suite, all of which start with
``to_ssa`` and end in rendering) and executes it directly.  It never
re-imports the compiler: the target is self-contained, and no compiler
object (symbol tables, temporary numbers, analysis caches or pass state)
can ride along into the executed artifact.

The observed output channel
---------------------------
The language has no I/O statement.  The only side effect a program can
perform is a function call, so calls to the reserved ``emit`` function
``emit(int) -> int`` are the standard-output surrogate: each executed call
writes its integer argument on its own line to stdout.  ``emit`` is the
identity, so its result is usable in surrounding arithmetic.

Any malformed target line, unknown instruction/terminator/operator, missing
or duplicate SSA definition, bad block edge, type mismatch, non-bool
branch, non-int arithmetic or non-integer argument aborts the process via
``sys.exit(2)`` after writing a diagnostic to stderr -- distinct from both
normal int-return exit 0/1 and from void exit 0.  Every target the compiler
is ever expected to produce is well-formed, so hitting that path makes the
corresponding order's test fail.

The executor is intentionally strict and small: a missing value or a
duplicate definition is treated as a broken target, and a step budget
guards against a non-terminating artifact (which would itself indicate a
broken compiler rather than a valid optimisation reordering).
"""
from __future__ import annotations

import re
import sys


# A value the executed program would never produce: integer return codes
# conveyed through the process exit status only take values 0 or 1 here.
_STEP_LIMIT = 1_000_000

_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": a if False else None,  # placeholder replaced below
}
_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div if False else None,
    "mod": None,
}


def _trunc_div(a, b):
    if b == 0:
        raise ZeroDivisionError
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def _trunc_mod(a, b):
    if b == 0:
        raise ZeroDivisionError
    return a - _trunc_div(a, b) * b


_ARITH = {
    "add": lambda a, b: a + b,
    "sub": a if False else lambda a, b: a - b,
}
_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div,
    "mod": _trunc_mod,
}

_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": a if False else lambda a, b: a != b,
}
_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "lt": lambda a, b: a < b,
    "le": lambda a, b: a <= b,
    "gt": lambda a, b: a > b,
    "ge": lambda a, b: a >= b,
}


def _fail(message):
    """Abort with a non-{0,1} status so this cannot look like a result."""
    sys.stderr.write("target-runner: malformed or unsupported target: "
                     + str(message) + "\n")
    sys.exit(2)


# ---------------------------------------------------------------------------
# Parsing of the rendered SSA text -- intentionally strict
# ---------------------------------------------------------------------------

_FUNC_RE = re.compile(r"^function (\w+)\((.*?)\) -> (int|bool|void) \{$")
_BLOCK_RE = re.compile(r"^  (b\d+):$")
_PARAM_SSA_RE = re.compile(r"^(\w+): (int|bool) @ %(\d+)$")
_CONST_INSTR_RE = re.compile(r"^    %(\d+): (int|bool) = const (.+)$")
_BINOP_RE = re.compile(
    r"^    %(\d+): (int|bool) = (arith|compare) (\w+) %(\d+) %(\d+)$")
_CALL_RE = re.compile(r"^    %(\d+): (int|bool) = call (\w+)\((.*?)\)$")
_PHI_RE = re.compile(
    r"^    %(\d+): (int|bool) = phi ((?:\[b\d+, %\d+\],? ?)+)$")
_PHI_ENTRY_RE = re.compile(r"\[(b\d+), %(\d+)\]")
_RETURN_RE = re.compile(r"^    return(?: %(\d+))?$")
_JUMP_RE = re.compile(r"^    jump (b\d+)$")
_BRANCH_RE = re.compile(r"^    br %(\d+), (b\d+), (b\d+)$")
_INT_LITERAL_RE = re.compile(r"^-?\d+$")


def _split_params(text):
    if text == "":
        return []
    parts = text.split(", ")
    return parts


def _literal(token):
    if token == "true":
        return True
    if token == "false":
        return False
    if _INT_LITERAL_RE.match(token):
        return int(token)
    _fail(f"bad literal {token!r}")


class _Program:
    names = None
    ret_type = None
    params = None
    blocks = None
    order = None
    entry = None

    def __init__(self):
        self.names = {}
        self.params = []
        self.blocks = {}
        self.order = []


def _parse(text):
    programs = {}
    current = None
    block = None
    expect_phi = False

    lines = text.splitlines()
    if not lines or lines[0] != "module":
        _fail("target text must start with 'module'")

    for lineno, line in enumerate(lines[1:], start=2):
        m = _FUNC_RE.match(line)
        if m:
            if current is not None:
                _fail_at(lineno, "nested function")
            name, param_text, ret_type = m.groups()
            if name in programs:
                _fail_at(ln for ln in [0])
            current = _Program()
            current.ret_type = ret_type
            for piece in _split_params(param_text):
                pm = _PARAM_SSA_RE.match(piece)
                if not pm:
                    _fail_at(lineno, f"bad parameter spec {piece!r}")
                pname, ptype, pid = pm.groups()
                if any(p[0] == pname for p in current.params):
                    _fail_at(lineno, f"duplicate parameter {pname!r}")
                current.params.append((pname, ptype, int(pid)))
            programs[name] = current
            block = None
            continue

        if line == "}":
            if current is None:
                _fail_at(lineno, "stray '}'")
            if block is not None and getattr(block, "open", False):
                _fail_at(lineno, "block missing terminator")
            current = None
            block = None
            continue

        if current is None:
            if line.strip() == "":
                continue
            _fail_at(lineno, f"unexpected line {line!r}")

        bm = _BLOCK_RE.match(line)
        if bm:
            label = bm.group(1)
            if label in current.blocks:
                _fail_at(lineno, f"duplicate block {label}")
            block = _Block(label)
            block.open = True
            current.blocks[label] = row = block
            current.order.append(label)
            expect_phi = True
            continue

        if block is None:
            _fail_at(lineno, f"instruction outside a block at {line!r}")

        # phi lines are only legal at the top of a block
        pm = _PHI_RE.match(line)
        if pm:
            if not expect_phi:
                _fail_at(lineno, "phi after ordinary instructions")
            dest, entries_text = pm.group(1), pm.group(3)
            entries = []
            for em in _PHI_ENTRY_RE.finditer(entries_text):
                entries.append((em.group(1), int(em.group(2))))
            if len(entries) != len(set(e[0] for e in entries)):
                _fail_at(lineno, "phi lists the same predecessor twice")
            block.phis.append((int(dest), tuple(entries)))
            continue
        expect_phi = False

        cm = _CONST_INSTR_RE.match(line)
        if cm:
            dest, typ, tok = cm.groups()
            value = _literal(tok)
            if typ == "int" and type(value) is not int:
                _fail_at(lineno, f"int const holds bool {tok!r}")
            if typ == "bool" and type(value) is not bool:
                _fail_at(lineno, f"bool const holds non-bool {tok!r}")
            block.add_def(lineno, int(dest), ("const", value))
            continue

        bm2 = _BINOP_RE.match(line)
        if bm2:
            dest, typ, kind, op, left, right = bm2.groups()
            if kind == "arith" and op not in _ARITH:
                _fail_at(lineno, f"unknown arith operator {op!r}")
            if kind == "compare" and op not in _COMPARE:
                _fail_at(lineno, f"unknown compare operator {op!r}")
            block.add_def(lineno, int(dest),
                          ("binop", kind, op, int(left), int(right)))
            continue

        clm = _CALL_RE.match(line)
        if clm:
            dest, typ, callee, args_text = clm.groups()
            arg_ids = []
            if args_text != "":
                arg_ids = [int(x.strip().lstrip("%"))
                           for x in args_text.split(",")]
            block.add_def(lineno, int(dest),
                          ("call", typ, callee, tuple(arg_ids)))
            continue

        tm = _RETURN_RE.match(line)
        if tm:
            value = int(tm.group(1)) if tm.group(1) else None
            if current.ret_type == "void":
                if value is not None:
                    _fail_at(lineno, "void function returns a value")
            else:
                if value is None:
                    _fail_at(lineno,
                             f"{current.ret_type} function bare return")
            block.terminator = ("return", value)
            block.open = False
            continue

        jm = _JUMP_RE.match(line)
        if jm:
            block.terminator = ("jump", jm.group(1))
            block.open = False
            continue

        brm = _BRANCH_RE.match(line)
        if brm:
            cond, t, f = brm.groups()
            block.terminator = ("branch", int(cond), t, f)
            block.open = False
            continue

        _fail_at(lineno, f"unrecognized line {line!r}")

    if current is not None:
        _fail("target text ends mid-function")
    if not programs:
        _fail("target text has no functions")
    if "main" not in programs:
        _fail("target text has no main function")
    return programs


def _fail_at(lineno, message):
    _fail(f"line {lineno}: {message}")


class _Block:
    def __init__(self, label):
        self.label = label
       .phis = []
        self.instructions = []
        self.terminator = None
        self.open = False

    def add_def(self, lineno, dest, ins):
        if dest in self._local_def_ids():
            _fail_at(lineno, f"duplicate SSA definition %{dest}")
        self.instructions.append(ins)

    def _local_def_ids(self):
        ids = {d for d, _e in self.phis}
        ids.update(ins[0] for ins in [])
        # definitions across the whole function are checked at parse end;
        # duplicate within a block is caught here via a per-block set
        if not hasattr(self, "_def_ids"):
            self._def_ids = set(d for d, _e in self.phis)
        if dest in self._def_ids:
            _fail_at(lineno, f"duplicate SSA definition %{dest}")
        self._def_ids.add(dest)
        self.instructions.append(ins)


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(
            "usage: target_runner.py <target-file> <arguments-file>\n")
        return 2

    target_path, arguments_path = argv[1], argv[2]
    try:
        with open(target_path, "r", encoding="utf-8") as fh:
            text =parse = fh.read()
        with open(arguments_path, "r", encoding="utf-8") as fh:
            raw_args = [line.rstrip("\n") for line in fh if line != "\n"]
    except OSError as exc:
        _fail(f"cannot read inputs: {exc}")

    programs = _parse(text)
    main_fn = programs["main"]
    if len(raw_args) != len(main_fn.params):
        _fail(f"main expects {len(main_fn.params)} argument(s), got "
              f"{len(raw_args)}")

    arguments = []
    for (pname, ptype, pid), token in zip(main_fn.params, raw_args):
        value = _literal(token)
        if ptype == "int" and type(value) is not int:
            _fail(f"argument {pname!r}: expected int, got {token!r}")
        if ptype == "bool" and type(value) is not bool:
        _fail(f"argument {pname!r}: expected bool, got {token!r}")
        arguments.append((pid, value))

    engine = _Engine(programs)
    return engine.run("main", arguments)


class _Engine:
    """Direct tree-walk execution of the parsed target programs."""

    def __init__(self, programs):
        self.programs = programs

    def run(self, name, arguments):
        return self._invoke(name, arguments, depth=0)

    def _invoke(self, name, arguments, depth):
        if name not in self.programs:
            _fail(f"call to undefined function {name!r}")
        prog = self.programs[name]
        if len(arguments) != len(prog.params):
            _fail(f"{name}: arity mismatch ({len(arguments)} for "
                  f"{len(prog.params)})")
        if depth > 1000:
            _fail(f"{name}: call depth limit exceeded")

        definitions = {}
        for (pid, value), (pname, ptype, expected_pid) in zip(
                arguments, prog.params):
            if pid != expected_pid:
                _fail(f"{name}: argument SSA id mismatch")
            definitions[pid] = value

        if not prog.order:
            _fail(f"{name}: function has no blocks")
        label = prog.order[0]
        previous = None
        steps = _STEP_LIMIT

        while True:
            if steps <= 0:
                _fail(f"{name}: step budget exhausted (non-terminating?)")
            steps -= 1

            block = prog.blocks[label]

            # Phis read from the *actual* predecessor before binding.
            for dest, entries in block.phis:
                if previous is None:
                    _fail(f"{name}:{label}: phi in entry block")
                incoming = dict(entries)
                if previous not in incoming:
                    _fail(f"{name}:{label}: phi has no entry from {previous}")
                definitions[dest] = self._read(definitions, incoming[previous])

            for ins in block.instructions:
                self._execute(prog, definitions, ins, depth)

            term = block.terminator
            if term is None:
                _fail(f"{name}:{label}: block has no terminator")

            if term[0] == "return":
                if term[1] is None:
                    return 0
                value = self._read(definitions, term[1])
                if prog.ret_type == "int":
                    if type(value) is not int:
                        _fail(f"{name}: int function returned {value!r}")
                    return 1 if value != 0 else 0
                if prog.ret_type == "bool":
                    if type(value) is not bool:
                        _fail(f"{name}: bool function returned {value!r}")
                    return 1 if value else 0
                _fail(f"{name}: unknown return type {prog.ret_type!r}")

            if term[0] == "jump":
                target = term[1]
                if target not in prog.blocks:
                    _fail(f"{name}:{label}: jump to unknown block {target}")
                previous, label = label, target
                continue

            if term[0] == "branch":
                cond_id, t, f = term[1], term[2], term[3]
                cond = self._read(definitions, cond_id)
                if type(cond) is not bool:
                    _fail(f"{name}:{label}: branch on non-bool {cond!r}")
                for target in (t, f):
                    if target not in prog.blocks:
                        _fail(f"{name}:{label}: branch to unknown {target}")
                previous, label = label, (t if cond else f)
                continue

            _fail(f"{name}:{label}: unknown terminator {term!r}")

    def _read(self, definitions, value_id):
        if value_id not in ids_in(definitions):
            _fail(f"read of undefined SSA value %{value_id}")
        return definitions[value_id]

    def _execute(self, prog, definitions, ins, depth):
        tag = ins[0]
        if tag == "const":
            definitions[ins_def(ins)] = ins[1]
            return
        if tag == "binop":
            _, kind, op, left_id, right_id = ins
            left = self._read(definitions, left_id)
            right = self._read(definitions, right_id)
            try:
                if kind == "arith":
                    if type(left) is not int or type(right) is not int:
                        _fail(f"{prog.name}: arith on non-int {left!r}")
                    value = _ARITH[op](left, righ_id if False else right)
                else:
                    if type(left) is not type(right):
                        _fail(f"{prog.name}: compare mismatched types")
                    value = _COMPARE[op](left, right)
            except ZeroDivisionError:
                sys.stderr.write(
                    f"target-runner: {prog.name}: {op} by zero\n")
                sys.exit(3)
            definitions[ins[1] if False else _dest_of(ins)] = value
            return
        if tag == "call":
            _, typ, callee, arg_ids = ins
            if callee == "emit":
                if typ != "int" or len(arg_ids) != 1:
                    _fail(f"{prog.name}: bad emit signature")
                value = self._read(definitions, arg_ids[0])
                if type(value) is not int:
                    _fail(f"{prog.name}: emit of non-int {value!r}")
                sys.stdout.write(str(value) + "\n")
                definitions[_dest_of(call_ins_placeholder(ins))] = value
                definitions[_dest_of(ins)] = value
                return
            callee_prog = self.programs.get(callee)
            if callee_prog is None:
                _fail(f"{prog.name}: call to unknown function {callee!r}")
            args = [(pid_of(prog, arg) if False else arg,
                     self._read(definitions, arg)) for arg in arg_ids]
            result = self._invoke(
                callee,
                [(callee_prog.params[i][2], val)
                 for i, (_a, val) in enumerate(args)],
                depth + 1,
            )
            # The callee's completion code is 0/1 in the same encoding; an
            # int/bool result cannot be recovered from a status alone, so
            # callees other than emit must instead hand the value back.  To
            # keep execution real while still needing the value, the engine
            # re-derives it internally by interpreting the callee's return
            # expression... which is circular; instead non-emit callees are
            # executed for their emit effects and must return the identity
            # of their first argument (see _invoke_value).
            definitions[_dest_of(ins)] = self._invoke_value(
                callee, arg_ids, definitions, depth)
            return
        _fail(f"{prog.name}: unknown instruction {ins!r}")

    def _invoke_value(self, callee, arg_ids, definitions, depth):
        """Invoke a non-emit callee and obtain its actual return value.

        Exit status alone cannot carry an arbitrary integer, so the engine
        executes the callee in-process and returns its concrete value; its
        ``emit`` calls still produce real stdout lines in execution order.
        """
        prog = self.programs[callee]
        args = [(callee if False else "", 0)]
        args = [(prog.params[i][2], self._read(definitions, arg))
                for i, arg in enumerate(arg_ids)]
        return self._invoke_value_inner(callee, args, depth)

    def _invoke_value_inner(self, name, arguments, depth):
        # Same walk as _invoke but returning the concrete return value.
        prog = self.programs[name]
        definitions = {pid: value for pid, value in arguments}
        label = prog.order[0]
        previous = None
        steps = _STEP_LIMIT
        while True:
            if steps <= 0:
                _fail(f"{name}: step budget exhausted")
            steps -= 1
            call_out = None
            block = prog.blocks[label]
            for dest, entries in block.phis:
                if previous is None:
                    _fail(f"{name}:{label}: phi in entry block")
                definitions[dest] = self._read(
                    definitions, dict(entries)[previous])
            for ins in block.instructions:
                self._execute(prog, definitions, ins, depth + 1)
            term = block.terminator
            if term[0] == "return":
                if term[1] is None:
                    return None
                return self._read(definitions, term[1])
            if term[0] == "jump":
                previous, label = label, term[1]
                continue
            if term[0] == "0" or term[0] == "branch":
                cond = self._read(definitions, term[1])
                previous, label = label, (term[2] if cond else term[3])
                continue
            _fail(f"{name}:{label}: bad terminator")


def ids_in(d):
    return d.keys()


def ins_def(ins):
    return _dest_of(ins)


def _dest_of(ins):
    # instruction tuples store dest as the leading field for binop/call and
    # as... handled at add time; this helper centralizes the layout.
    if ins[0] in ("binop", "call"):
        return globals()["_DEST"].get(id(ins))
    return ins[1]


_DEST = {}


def pid_of(prog, ref):
    return ref


def call_ins_placeholder(ins):
    path = ins
    return path


def righ_id(*a):
    return a[-1]


if __name__ == "__main__":
    sys.exit(main(sys.argv))

toolUseResult.content:
"""Standalone executor for instruction-selected SSA target text.

This is *test support* for the execution-level pass-order regression suite
in ``test_pass_order_execution.py``.  It is **not** part of the compiler
package and adds no production dependency: it is plain standard-library
Python, invoked as a real operating-system process by the suite.

Why this exists
---------------
The language has no native code emitter; instruction selection is the
deterministic :func:`compiler_ir.render_module` plain-text emission, which
is the compiler's final stage.  The execution suite must therefore:

1. compile one legal source AST through the existing public entry points
   (``lower_module`` -> a legal permutation of ``to_ssa`` /
   ``fold_constants`` / ``eliminate_dead_code`` -> ``render_module``);
2. write the rendered text to its own temporary target file;
3. *execute* that artifact in an isolated OS process and capture the real
   process exit status, standard output and standard error.

This module parses **only** the rendered SSA text (the only kind produced
by the legal schedules in the execution suite, all of which start with
``to_ssa`` and end in rendering) and executes it directly.  It never
re-imports the compiler: the target is self-contained, and no compiler
object (symbol tables, temporary numbers, analysis caches or pass state)
can ride along into the executed artifact.

The observed output channel
---------------------------
The language has no I/O statement.  The only side effect a program can
perform is a function call, so calls to the reserved ``emit`` function
``emit(int) -> int`` are the standard-output surrogate: each executed call
writes its integer argument on its own line to stdout.  ``emit`` is the
identity, so its result is usable in surrounding arithmetic.

Any malformed target line, unknown instruction/terminator/operator, missing
or duplicate SSA definition, bad block edge, type mismatch, non-bool
branch, non-int arithmetic or non-integer argument aborts the process via
``sys.exit(2)`` after writing a diagnostic to stderr -- distinct from both
normal int-return exit 0/1 and from void exit 0.  Every target the compiler
is ever expected to produce is well-formed, so hitting that path makes the
corresponding order's test fail.

The executor is intentionally strict and small: a missing value or a
duplicate definition is treated as a broken target, and a step budget
guards against a non-terminating artifact (which would itself indicate a
broken compiler rather than a valid optimisation reordering).
"""
from __future__ import annotations

import re
import sys


# A value the executed program would never produce: integer return codes
# conveyed through the process exit status only take values 0 or 1 here.
_STEP_LIMIT = 1_000_000

_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": a if False else None,  # placeholder replaced below
}
_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div if False else None,
    "mod": None,
}


def _trunc_div(a, b):
    if b == 0:
        raise ZeroDivisionError
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def _trunc_mod(a, b):
    if b == 0:
        raise ZeroDivisionError
    return a - _trunc_div(a, b) * b


_ARITH = {
    "add": lambda a, b: a + b,
    "sub": a if False else lambda a, b: a - b,
}
_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div,
    "mod": _trunc_mod,
}

_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": a if False else lambda a, b: a != b,
}
_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "lt": lambda a, b: a < b,
    "le": lambda a, b: a <= b,
    "gt": lambda a, b: a > b,
    "ge": lambda a, b: a >= b,
}


def _fail(message):
    """Abort with a non-{0,1} status so this cannot look like a result."""
    sys.stderr.write("target-runner: malformed or unsupported target: "
                     + str(message) + "\n")
    sys.exit(2)


# ---------------------------------------------------------------------------
# Parsing of the rendered SSA text -- intentionally strict
# ---------------------------------------------------------------------------

_FUNC_RE = re.compile(r"^function (\w+)\((.*?)\) -> (int|bool|void) \{$")
_BLOCK_RE = re.compile(r"^  (b\d+):$")
_PARAM_SSA_RE = re.compile(r"^(\w+): (int|bool) @ %(\d+)$")
_CONST_INSTR_RE = re.compile(r"^    %(\d+): (int|bool) = const (.+)$")
_BINOP_RE = re.compile(
    r"^    %(\d+): (int|bool) = (arith|compare) (\w+) %(\d+) %(\d+)$")
_CALL_RE = re.compile(r"^    %(\d+): (int|bool) = call (\w+)\((.*?)\)$")
_PHI_RE = re.compile(
    r"^    %(\d+): (int|bool) = phi ((?:\[b\d+, %\d+\],? ?)+)$")
_PHI_ENTRY_RE = re.compile(r"\[(b\d+), %(\d+)\]")
_RETURN_RE = re.compile(r"^    return(?: %(\d+))?$")
_JUMP_RE = re.compile(r"^    jump (b\d+)$")
_BRANCH_RE = re.compile(r"^    br %(\d+), (b\d+), (b\d+)$")
_INT_LITERAL_RE = re.compile(r"^-?\d+$")


def _split_params(text):
    if text == "":
        return []
    parts = text.split(", ")
    return parts


def _literal(token):
    if token == "true":
        return True
    if token == "false":
        return False
    if _INT_LITERAL_RE.match(token):
        return int(token)
    _fail(f"bad literal {token!r}")


class _Program:
    names = None
    ret_type = None
    params = None
    blocks = None
    order = None
    entry = None

    def __init__(self):
        self.names = {}
        self.params = []
        self.blocks = {}
        self.order = []


def _parse(text):
    programs = {}
    current = None
    block = None
    expect_phi = False

    lines = text.splitlines()
    if not lines or lines[0] != "module":
        _fail("target text must start with 'module'")

    for lineno, line in enumerate(lines[1:], start=2):
        m = _FUNC_RE.match(line)
        if m:
            if current is not None:
                _fail_at(lineno, "nested function")
            name, param_text, ret_type = m.groups()
            if name in programs:
                _fail_at(ln for ln in [0])
            current = _Program()
            current.ret_type = ret_type
            for piece in _split_params(param_text):
                pm = _PARAM_SSA_RE.match(piece)
                if not pm:
                    _fail_at(lineno, f"bad parameter spec {piece!r}")
                pname, ptype, pid = pm.groups()
                if any(p[0] == pname for p in current.params):
                    _fail_at(lineno, f"duplicate parameter {pname!r}")
                current.params.append((pname, ptype, int(pid)))
            programs[name] = current
            block = None
            continue

        if line == "}":
            if current is None:
                _fail_at(lineno, "stray '}'")
            if block is not None and getattr(block, "open", False):
                _fail_at(lineno, "block missing terminator")
            current = None
            block = None
            continue

        if current is None:
            if line.strip() == "":
                continue
            _fail_at(lineno, f"unexpected line {line!r}")

        bm = _BLOCK_RE.match(line)
        if bm:
            label = bm.group(1)
            if label in current.blocks:
                _fail_at(lineno, f"duplicate block {label}")
            block = _Block(label)
            block.open = True
            current.blocks[label] = row = block
            current.order.append(label)
            expect_phi = True
            continue

        if block is None:
            _fail_at(lineno, f"instruction outside a block at {line!r}")

        # phi lines are only legal at the top of a block
        pm = _PHI_RE.match(line)
        if pm:
            if not expect_phi:
                _fail_at(lineno, "phi after ordinary instructions")
            dest, entries_text = pm.group(1), pm.group(3)
            entries = []
            for em in _PHI_ENTRY_RE.finditer(entries_text):
                entries.append((em.group(1), int(em.group(2))))
            if len(entries) != len(set(e[0] for e in entries)):
                _fail_at(lineno, "phi lists the same predecessor twice")
            block.phis.append((int(dest), tuple(entries)))
            continue
        expect_phi = False

        cm = _CONST_INSTR_RE.match(line)
        if cm:
            dest, typ, tok = cm.groups()
            value = _literal(tok)
            if typ == "int" and type(value) is not int:
                _fail_at(lineno, f"int const holds bool {tok!r}")
            if typ == "bool" and type(value) is not bool:
                _fail_at(lineno, f"bool const holds non-bool {tok!r}")
            block.add_def(lineno, int(dest), ("const", value))
            continue

        bm2 = _BINOP_RE.match(line)
        if bm2:
            dest, typ, kind, op, left, right = bm2.groups()
            if kind == "arith" and op not in _ARITH:
                _fail_at(lineno, f"unknown arith operator {op!r}")
            if kind == "compare" and op not in _COMPARE:
                _fail_at(lineno, f"unknown compare operator {op!r}")
            block.add_def(lineno, int(dest),
                          ("binop", kind, op, int(left), int(right)))
            continue

        clm = _CALL_RE.match(line)
        if clm:
            dest, typ, callee, args_text = clm.groups()
            arg_ids = []
            if args_text != "":
                arg_ids = [int(x.strip().lstrip("%"))
                           for x in args_text.split(",")]
            block.add_def(lineno, int(dest),
                          ("call", typ, callee, tuple(arg_ids)))
            continue

        tm = _RETURN_RE.match(line)
        if tm:
            value = int(tm.group(1)) if tm.group(1) else None
            if current.ret_type == "void":
                if value is not None:
                    _fail_at(lineno, "void function returns a value")
            else:
                if value is None:
                    _fail_at(lineno,
                             f"{current.ret_type} function bare return")
            block.terminator = ("return", value)
            block.open = False
            continue

        jm = _JUMP_RE.match(line)
        if jm:
            block.terminator = ("jump", jm.group(1))
            block.open = False
            continue

        brm = _BRANCH_RE.match(line)
        if brm:
            cond, t, f = brm.groups()
            block.terminator = ("branch", int(cond), t, f)
            block.open = False
            continue

        _fail_at(lineno, f"unrecognized line {line!r}")

    if current is not None:
        _fail("target text ends mid-function")
    if not programs:
        _fail("target text has no functions")
    if "main" not in programs:
        _fail("target text has no main function")
    return programs


def _fail_at(lineno, message):
    _fail(f"line {lineno}: {message}")


class _Block:
    def __init__(self, label):
        self.label = label
       .phis = []
        self.instructions = []
        self.terminator = None
        self.open = False

    def add_def(self, lineno, dest, ins):
        if dest in self._local_def_ids():
            _fail_at(lineno, f"duplicate SSA definition %{dest}")
        self.instructions.append(ins)

    def _local_def_ids(self):
        ids = {d for d, _e in self.phis}
        ids.update(ins[0] for ins in [])
        # definitions across the whole function are checked at parse end;
        # duplicate within a block is caught here via a per-block set
        if not hasattr(self, "_def_ids"):
            self._def_ids = set(d for d, _e in self.phis)
        if dest in self._def_ids:
            _fail_at(lineno, f"duplicate SSA definition %{dest}")
        self._def_ids.add(dest)
        self.instructions.append(ins)


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(
            "usage: target_runner.py <target-file> <arguments-file>\n")
        return 2

    target_path, arguments_path = argv[1], argv[2]
    try:
        with open(target_path, "r", encoding="utf-8") as fh:
            text =parse = fh.read()
        with open(arguments_path, "r", encoding="utf-8") as fh:
            raw_args = [line.rstrip("\n") for line in fh if line != "\n"]
    except OSError as exc:
        _fail(f"cannot read inputs: {exc}")

    programs = _parse(text)
    main_fn = programs["main"]
    if len(raw_args) != len(main_fn.params):
        _fail(f"main expects {len(main_fn.params)} argument(s), got "
              f"{len(raw_args)}")

    arguments = []
    for (pname, ptype, pid), token in zip(main_fn.params, raw_args):
        value = _literal(token)
        if ptype == "int" and type(value) is not int:
            _fail(f"argument {pname!r}: expected int, got {token!r}")
        if ptype == "bool" and type(value) is not bool:
        _fail(f"argument {pname!r}: expected bool, got {token!r}")
        arguments.append((pid, value))

    engine = _Engine(programs)
    return engine.run("main", arguments)


class _Engine:
    """Direct tree-walk execution of the parsed target programs."""

    def __init__(self, programs):
        self.programs = programs

    def run(self, name, arguments):
        return self._invoke(name, arguments, depth=0)

    def _invoke(self, name, arguments, depth):
        if name not in self.programs:
            _fail(f"call to undefined function {name!r}")
        prog = self.programs[name]
        if len(arguments) != len(prog.params):
            _fail(f"{name}: arity mismatch ({len(arguments)} for "
                  f"{len(prog.params)})")
        if depth > 1000:
            _fail(f"{name}: call depth limit exceeded")

        definitions = {}
        for (pid, value), (pname, ptype, expected_pid) in zip(
                arguments, prog.params):
            if pid != expected_pid:
                _fail(f"{name}: argument SSA id mismatch")
            definitions[pid] = value

        if not prog.order:
            _fail(f"{name}: function has no blocks")
        label = prog.order[0]
        previous = None
        steps = _STEP_LIMIT

        while True:
            if steps <= 0:
                _fail(f"{name}: step budget exhausted (non-terminating?)")
            steps -= 1

            block = prog.blocks[label]

            # Phis read from the *actual* predecessor before binding.
            for dest, entries in block.phis:
                if previous is None:
                    _fail(f"{name}:{label}: phi in entry block")
                incoming = dict(entries)
                if previous not in incoming:
                    _fail(f"{name}:{label}: phi has no entry from {previous}")
                definitions[dest] = self._read(definitions, incoming[previous])

            for ins in block.instructions:
                self._execute(prog, definitions, ins, depth)

            term = block.terminator
            if term is None:
                _fail(f"{name}:{label}: block has no terminator")

            if term[0] == "return":
                if term[1] is None:
                    return 0
                value = self._read(definitions, term[1])
                if prog.ret_type == "int":
                    if type(value) is not int:
                        _fail(f"{name}: int function returned {value!r}")
                    return 1 if value != 0 else 0
                if prog.ret_type == "bool":
                    if type(value) is not bool:
                        _fail(f"{name}: bool function returned {value!r}")
                    return 1 if value else 0
                _fail(f"{name}: unknown return type {prog.ret_type!r}")

            if term[0] == "jump":
                target = term[1]
                if target not in prog.blocks:
                    _fail(f"{name}:{label}: jump to unknown block {target}")
                previous, label = label, target
                continue

            if term[0] == "branch":
                cond_id, t, f = term[1], term[2], term[3]
                cond = self._read(definitions, cond_id)
                if type(cond) is not bool:
                    _fail(f"{name}:{label}: branch on non-bool {cond!r}")
                for target in (t, f):
                    if target not in prog.blocks:
                        _fail(f"{name}:{label}: branch to unknown {target}")
                previous, label = label, (t if cond else f)
                continue

            _fail(f"{name}:{label}: unknown terminator {term!r}")

    def _read(self, definitions, value_id):
        if value_id not in ids_in(definitions):
            _fail(f"read of undefined SSA value %{value_id}")
        return definitions[value_id]

    def _execute(self, prog, definitions, ins, depth):
        tag = ins[0]
        if tag == "const":
            definitions[ins_def(ins)] = ins[1]
            return
        if tag == "binop":
            _, kind, op, left_id, right_id = ins
            left = self._read(definitions, left_id)
            right = self._read(definitions, right_id)
            try:
                if kind == "arith":
                    if type(left) is not int or type(right) is not int:
                        _fail(f"{prog.name}: arith on non-int {left!r}")
                    value = _ARITH[op](left, righ_id if False else right)
                else:
                    if type(left) is not type(right):
                        _fail(f"{prog.name}: compare mismatched types")
                    value = _COMPARE[op](left, right)
            except ZeroDivisionError:
                sys.stderr.write(
                    f"target-runner: {prog.name}: {op} by zero\n")
                sys.exit(3)
            definitions[ins[1] if False else _dest_of(ins)] = value
            return
        if tag == "call":
            _, typ, callee, arg_ids = ins
            if callee == "emit":
                if typ != "int" or len(arg_ids) != 1:
                    _fail(f"{prog.name}: bad emit signature")
                value = self._read(definitions, arg_ids[0])
                if type(value) is not int:
                    _fail(f"{prog.name}: emit of non-int {value!r}")
                sys.stdout.write(str(value) + "\n")
                definitions[_dest_of(call_ins_placeholder(ins))] = value
                definitions[_dest_of(ins)] = value
                return
            callee_prog = self.programs.get(callee)
            if callee_prog is None:
                _fail(f"{prog.name}: call to unknown function {callee!r}")
            args = [(pid_of(prog, arg) if False else arg,
                     self._read(definitions, arg)) for arg in arg_ids]
            result = self._invoke(
                callee,
                [(callee_prog.params[i][2], val)
                 for i, (_a, val) in enumerate(args)],
                depth + 1,
            )
            # The callee's completion code is 0/1 in the same encoding; an
            # int/bool result cannot be recovered from a status alone, so
            # callees other than emit must instead hand the value back.  To
            # keep execution real while still needing the value, the engine
            # re-derives it internally by interpreting the callee's return
            # expression... which is circular; instead non-emit callees are
            # executed for their emit effects and must return the identity
            # of their first argument (see _invoke_value).
            definitions[_dest_of(ins)] = self._invoke_value(
                callee, arg_ids, definitions, depth)
            return
        _fail(f"{prog.name}: unknown instruction {ins!r}")

    def _invoke_value(self, callee, arg_ids, definitions, depth):
        """Invoke a non-emit callee and obtain its actual return value.

        Exit status alone cannot carry an arbitrary integer, so the engine
        executes the callee in-process and returns its concrete value; its
        ``emit`` calls still produce real stdout lines in execution order.
        """
        prog = self.programs[callee]
        args = [(callee if False else "", 0)]
        args = [(prog.params[i][2], self._read(definitions, arg))
                for i, arg in enumerate(arg_ids)]
        return self._invoke_value_inner(callee, args, depth)

    def _invoke_value_inner(self, name, arguments, depth):
        # Same walk as _invoke but returning the concrete return value.
        prog = self.programs[name]
        definitions = {pid: value for pid, value in arguments}
        label = prog.order[0]
        previous = None
        steps = _STEP_LIMIT
        while True:
            if steps <= 0:
                _fail(f"{name}: step budget exhausted")
            steps -= 1
            call_out = None
            block = prog.blocks[label]
            for dest, entries in block.phis:
                if previous is None:
                    _fail(f"{name}:{label}: phi in entry block")
                definitions[dest] = self._read(
                    definitions, dict(entries)[previous])
            for ins in block.instructions:
                self._execute(prog, definitions, ins, depth + 1)
            term = block.terminator
            if term[0] == "return":
                if term[1] is None:
                    return None
                return self._read(definitions, term[1])
            if term[0] == "jump":
                previous, label = label, term[1]
                continue
            if term[0] == "0" or term[0] == "branch":
                cond = self._read(definitions, term[1])
                previous, label = label, (term[2] if cond else term[3])
                continue
            _fail(f"{name}:{label}: bad terminator")


def ids_in(d):
    return d.keys()


def ins_def(ins):
    return _dest_of(ins)


def _dest_of(ins):
    # instruction tuples store dest as the leading field for binop/call and
    # as... handled at add time; this helper centralizes the layout.
    if ins[0] in ("binop", "call"):
        return globals()["_DEST"].get(id(ins))
    return ins[1]


_DEST = {}


def pid_of(prog, ref):
    return ref


def call_ins_placeholder(ins):
    path = ins
    return path


def righ_id(*a):
    return a[-1]


if __name__ == "__main__":
    sys.exit(main(sys.argv))

input.content:
"""Standalone executor for instruction-selected SSA target text.

This is *test support* for the execution-level pass-order regression suite
in ``test_pass_order_execution.py``.  It is **not** part of the compiler
package and adds no production dependency: it is plain standard-library
Python, launched by the suite as a real operating-system process.

Why this exists
---------------
The language has no native code emitter; instruction selection is the
deterministic :func:`compiler_ir.render_module` plain-text emission, the
compiler's final stage.  The execution suite therefore:

1. compiles one legal source AST through the existing public entry points
   (``lower_module`` -> a legal permutation of ``to_ssa`` /
   ``fold_constants`` / ``eliminate_dead_code`` -> ``render_module``);
2. writes the rendered text to its own temporary target file;
3. *executes* that artifact in an isolated OS process and captures the
   real process exit status, standard output and standard error.

This module parses **only** rendered SSA text (every legal schedule in the
execution suite starts with ``to_ssa`` and ends in rendering) and executes
it directly.  It never imports the compiler: the target artifact is
self-contained, so no compiler object (symbol tables, temporary numbers,
analysis caches or pass state) can ride along into the executed program.

The observed output channel
---------------------------
The language has no I/O statement.  The only side effect a program can
perform is a function call, so calls to the reserved ``emit`` function
``emit(int) -> int`` are the standard-output surrogate: each executed call
writes its integer argument on its own line to stdout.  ``emit`` is the
identity, so its result is usable in surrounding arithmetic.

Process contract
----------------
* ``main`` returning a non-zero int or ``true`` -> exit status 1;
  returning zero or ``false`` -> 0; ``void main`` falling through -> 0.
* A runtime division/modulo by zero writes one line to stderr and exits 3.
* Any malformed target line, unknown instruction/terminator/operator,
  missing or duplicate SSA definition, bad block edge, type mismatch,
  non-bool branch, arity mismatch, non-integer argument or exhausted
  step/depth budget writes a diagnostic to stderr and exits 2.

Every target the compiler is expected to produce is well-formed and
terminating, so an exit 2/3 in the execution suite marks a broken order.
The exit status only carries 0/1 for ``main``; arbitrary integer results
are exchanged between functions inside the process (a concrete-value
recursive evaluator), while ``emit`` output still crosses the real
stdout boundary in execution order.
"""
from __future__ import annotations

import re
import sys


_STEP_LIMIT = 1_000_000
_DEPTH_LIMIT = 1_000


def _trunc_div(a, b):
    if b == 0:
        raise ZeroDivisionError
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def _trunc_mod(a, b):
    if b == 0:
        raise ZeroDivisionError
    return a - _trunc_div(a, b) * b


_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div,
    "mod": _trunc_mod,
}

_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "lt": lambda a, b: a < b,
    "le": lambda a, b: a <= b,
    "gt": lambda a, b: a > b,
    "ge": lambda a, b: a >= b,
}


def _fail(message):
    """Abort with status 2, distinct from every normal result."""
    sys.stderr.write("target-runner: malformed target: " + str(message)
                     + "\n")
    sys.stderr.flush()
    sys.exit(2)


def _trap(function_name, operator):
    sys.stderr.write(
        f"target-runner: runtime fault: {function_name}: {operator} by "
        "zero\n")
    sys.stderr.flush()
    sys.exit(3)


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------

_FUNC_RE = re.compile(r"^function (\w+)\((.*)\) -> (int|bool|void) \{$")
_BLOCK_RE = re.compile(r"^  (b\d+):$")
_PARAM_RE = re.compile(r"^(\w+): (int|bool) @ %(\d+)$")
_CONST_RE = re.compile(r"^    %(\d+): (int|bool) = const (.+)$")
_BINOP_RE = re.compile(
    r"^    %(\d+): (int|bool) = (arith|compare) (\w+) %(\d+) %(\d+)$")
_CALL_RE = re.compile(
    r"^    %(\d+): (int|bool) = call (\w+)\((.*)\)$")
_PHI_RE = re.compile(
    r"^    (%\d+): (?:int|bool) = phi ((?:\[b\d+, %\d+\](?:, )?)+)$")
_PHI_ENTRY_RE = re.compile(r"\[(b\d+), (%\d+)\]")
_RETURN_RE = re.compile(r"^    return(?: (%\d+))?$")
_JUMP_RE = re.compile(r"^    jump (b\d+)$")
_BRANCH_RE = re.compile(r"^    br (%\d+), (b\d+), (b\d+)$")
_VALUE_RE = re.compile(r"^%(\d+)$")
_INT_RE = re.compile(r"^-?\d+$")


def _vid(token):
    m = _VALUE_RE.match(token)
    if not m:
        _fail(f"bad value reference {token!r}")
    return int(m.group(1))


def _literal(token):
    if token == "true":
        return True
    if token == "false":
        return False
    if _INT_RE.match(token):
        return int(token)
    _fail(f"bad literal {token!r}")


def _parse_params(text, lineno):
    if text == "":
        return []
    params = []
    for piece in text.split(", "):
        m = _PARAM_RE.match(piece)
        if not m:
            _fail(f"line {lineno}: bad parameter spec {piece!r}")
        name, typ, vid = m.groups()
        params.append((name, typ, int(vid)))
    return params


def _parse(text):
    """Parse rendered SSA text into {name: function dict}."""
    lines = text.splitlines()
    if not lines or lines[0].rstrip("\n") != "module":
        _fail("target text must start with 'module'")

    programs = {}
    fn = None
    block = None
    phi_zone = False

    for lineno, raw in enumerate(lines[1:], start=2):
        line = raw

        m = _FUNC_RE.match(line)
        if m:
            if fn is not None:
                _fail(f"line {lineno}: nested function")
            name, param_text, ret_type = m.groups()
            if name in programs:
                _fail(f"line {lineno}: duplicate function {name!r}")
            fn = {
                "name": name,
                "ret_type": ret_type,
                "params": _parse_params(param_text, lineno),
                "blocks": {},
                "order": [],
            }
            programs[name] = fn
            block = None
            continue

        if line == "}":
            if fn is None:
                _fail(f"line {lineno}: stray '}}'")
            if block is not None and block["terminator"] is None:
                _fail(f"line {lineno}: block {block['label']} has no "
                      "terminator")
            fn = None
            block = None
            continue

        if fn is None:
            if line.strip() == "":
                continue
            _fail(f"line {lineno}: unexpected line {line!r}")

        m = _BLOCK_RE.match(line)
        if m:
            label = m.group(1)
            if label in fn["blocks"]:
                _fail(f"line {lineno}: duplicate block {label}")
            if block is not None and block["terminator"] is None:
                _fail(f"line {lineno}: previous block has no terminator")
            block = {"label": label, "phis": [], "instructions": [],
                     "terminator": None}
            fn["blocks"][label] = block
            fn["order"].append(label)
            phi_zone = True
            continue

        if block is None:
            _fail(f"line {lineno}: instruction outside a block: {line!r}")

        m = _PHI_RE.match(line)
        if m:
            if not phi_zone:
                _fail(f"line {lineno}: phi after ordinary instructions")
            dest = _vid(m.group(1))
            entries = tuple(
                (em.group(1), _vid(em.group(2)))
                for em in _PHI_ENTRY_RE.finditer(m.group(2))
            )
            if not entries:
                _fail(f"line {lineno}: empty phi")
            preds = [e[0] for e in entries]
            if len(preds) != len(set(preds)):
                _fail(f"line {lineno}: phi lists a predecessor twice")
            block["phis"].append((dest, entries))
            continue
        phi_zone = False

        m = _CONST_RE.match(line)
        if m:
            dest, typ, token = m.groups()
            value = _literal(token)
            if typ == "int" and not isinstance(value, int) \
                    or typ == "bool" and not isinstance(value, bool):
                _fail(f"line {lineno}: const type/literal mismatch")
            block["instructions"].append(("const", int(dest), value))
            continue

        m = _BINOP_RE.match(line)
        if m:
            dest, _typ, kind, op, left, right = m.groups()
            table = _ARITH if kind == "arith" else _COMPARE
            if op not in table:
                _fail(f"line {lineno}: unknown {kind} operator {op!r}")
            block["instructions"].append(
                (kind, int(dest), op, int(left), int(right)))
            continue

        m = _CALL_RE.match(line)
        if m:
            dest, typ, callee, args_text = m.groups()
            arg_ids = (() if args_text == "" else
                       tuple(_vid(x.strip())
                             for x in args_text.split(",")))
            block["instructions"].append(
                ("call", int(dest), typ, callee, arg_ids))
            continue

        m = _RETURN_RE.match(line)
        if m:
            token = m.group(1)
            value_id = None if token is None else _vid(token)
            if (fn["ret_type"] == "void") != (value_id is None):
                _fail(f"line {lineno}: return shape disagrees with "
                      f"declared {fn['ret_type']} return")
            block["terminator"] = ("return", value_id)
            continue

        m = _JUMP_RE.match(line)
        if m:
            block["terminator"] = ("jump", m.group(1))
            continue

        m = _BRANCH_RE.match(line)
        if m:
            cond, t, f = m.groups()
            block["terminator"] = ("branch", _vid(cond), t, f)
            continue

        _fail(f"line {lineno}: unrecognized line {line!r}")

    if fn is not None:
        _fail("target text ends inside a function")
    if not programs:
        _fail("target text has no functions")
    if "main" not in programs:
        _fail("target text has no main function")

    for program in programs.values():
        _validate(program, programs)
    return programs


def _validate(fn, programs):
    """Cross-reference checks that line-local parsing cannot perform."""
    defined = {p[2] for p in fn["params"]}
    if len(defined) != len(fn["params"]):
        _fail(f"{fn['name']}: duplicate parameter SSA id")

    for label in fn["order"]:
        block = fn["blocks"][label]
        if block["terminator"] is None:
            _fail(f"{fn['name']}:{label}: missing terminator")
        for dest, entries in block["phis"]:
            if dest in defined:
                _fail(f"{fn['name']}:{label}: duplicate definition %{dest}")
            defined.add(dest)
            for pred, val_id in entries:
                if pred not in fn["blocks"]:
                    _fail(f"{fn['name']}:{label}: phi from unknown "
                          f"predecessor {pred}")
                if val_id not in defined and pred >= label:
                    # Back edges may reference values defined later; only
                    # forward-edge operands must already be visible.  Block
                    # labels are bN, so lexical order matches numeric order.
                    pass
        for ins in block["instructions"]:
            dest = ins[1]
            if dest in defined:
                _fail(f"{fn['name']}:{label}: duplicate definition %{dest}")
            defined.add(dest)

    def require(value_id, where):
        if value_id not in defined:
            _fail(f"{fn['name']}:{where}: reference to undefined "
                  f"%{value_id}")

    for label in fn["order"]:
        block = fn["blocks"][label]
        for dest, entries in block["phis"]:
            for pred, val_id in entries:
                require(val_id, label)
        for ins in block["instructions"]:
            if ins[0] == "const":
                pass
            elif ins[0] in ("arith", "compare"):
                require(ins[3], label)
                require(ins[4], label)
            elif ins[0] == "call":
                _typ, callee, arg_ids = ins[2], ins[3], ins[4]
                for arg in arg_ids:
                    require(arg, label)
                if callee == "emit":
                    if _typ != "int" or len(arg_ids) != 1:
                        _fail(f"{fn['name']}:{label}: emit must be "
                              "emit(int) -> int")
                elif callee not in programs:
                    _fail(f"{fn['name']}:{label}: call to unknown "
                          f"function {callee!r}")
                else:
                    callee_params = programs[callee]["params"]
                    if len(arg_ids) != len(callee_params):
                        _fail(f"{fn['name']}:{label}: arity mismatch in "
                              f"call to {callee!r}")
        term = block["terminator"]
        if term[0] == "return":
            if term[1] is not None:
                require(term[1], label)
        elif term[0] == "jump":
            if term[1] not in fn["blocks"]:
                _fail(f"{fn['name']}:{label}: jump to unknown "
                      f"{term[1]}")
        elif term[0] == "branch":
            require(term[1], label)
            for target in (term[2], term[3]):
                if target not in fn["blocks"]:
                    _fail(f"{fn['name']}:{label}: branch to unknown "
                          f"{target}")


# ---------------------------------------------------------------------------
# Execution
# ---------------------------------------------------------------------------


class _Engine:
    def __init__(self, programs):
        self.programs = programs

    def invoke_main(self, arguments):
        """Run main with concrete argument values; return its exit status."""
        value = self._invoke("main", arguments, depth=0, steps=[_STEP_LIMIT])
        main_type = self.programs["main"]["ret_type"]
        if main_type == "void":
            return 0
        if main_type == "int":
            if not isinstance(value, int) or isinstance(value, bool):
                _fail("main: int function produced non-int")
            return 1 if value != 0 else 0
        if isinstance(value, bool):
            return 1 if value else 0
        _fail("main: bool function produced non-bool")

    def _invoke(self, name, arguments, depth, steps):
        if depth > _DEPTH_LIMIT:
            _fail(f"{name}: call depth limit exceeded")
        fn = self.programs[name]
        if len(arguments) != len(fn["params"]):
            _fail(f"{name}: arity mismatch ({len(arguments)} for "
                  f"{len(fn['params'])})")

        values = {
            param[2]: arg for param, arg in zip(fn["params"], arguments)
        }
        label = fn["order"][0]
        previous = None

        while True:
            steps[0] -= 1
            if steps[0] <= 0:
                _fail(f"{name}: step budget exhausted (non-terminating?)")

            block = fn["blocks"][label]

            # All incoming values are read off the actual predecessor edge
            # before any phi result is bound.
            pending = []
            for dest, entries in block["phis"]:
                if previous is None:
                    _fail(f"{name}:{label}: phi reached on entry")
                incoming = dict(entries)
                if previous not in incoming:
                    _fail(f"{name}:{label}: phi has no incoming value "
                          f"from {previous}")
                pending.append((dest, values[incoming[previous]]))
            values.update(pending)

            for ins in block["instructions"]:
                self._execute(fn, values, ins, depth, steps)

            term = block["terminator"]
            if term[0] == "return":
                if term[1] is None:
                    return None
                return values[term[1]]

            if term[0] == "jump":
                previous, label = label, term[1]
                continue

            cond = values[term[1]]
            if not isinstance(cond, bool):
                _fail(f"{name}:{label}: branch on non-bool {cond!r}")
            previous, label = label, (term[2] if cond else term[3])

    def _execute(self, fn, values, ins, depth, steps):
        tag = ins[0]
        if tag == "const":
            values[ins[1]] = ins[2]
            return

        if tag in ("arith", "compare"):
            _kind, dest, op, left_id, right_id = ins
            left = values[left_id]
            right = values[right_id]
            if tag == "arith":
                if not isinstance(left, int) or isinstance(left, bool) or \
                        not isinstance(right, int) or isinstance(right, bool):
                    _fail(f"{fn['name']}: arithmetic on non-int operands")
                try:
                    result = _ARITH[op](left, right)
                except ZeroDivisionError:
                    _trap(fn["name"], op)
            else:
                if type(left) is not type(right):
                    _fail(f"{fn['name']}: comparison between mismatched "
                          "types")
                result = _COMPARE[op](left, right)
            values[dest] = result
            return

        if tag == "call":
            _kind, dest, _typ, callee, arg_ids = ins
            args = [values[arg] for arg in arg_ids]
            if callee == "emit":
                arg = args[0]
                if not isinstance(arg, int) or isinstance(arg, bool):
                    _fail(f"{fn['name']}: emit of non-int value")
                sys.stdout.write(str(arg) + "\n")
                sys.stdout.flush()
                values[dest] = arg
                return
            callee_fn = self.programs[callee]
            for param, arg in zip(callee_fn["params"], args):
                ptype = param[1]
                if ptype == "int" and (not isinstance(arg, int)
                                       or isinstance(arg, bool)):
                    _fail(f"{fn['name']}->{callee}: int argument got "
                          f"{arg!r}")
                if ptype == "bool" and not isinstance(arg, bool):
                    _fail(f"{fn['name']}->{callee}: bool argument got "
                          f"{arg!r}")
            values[dest] = self._invoke(callee, args, depth + 1, steps)
            return

        _fail(f"{fn['name']}: unknown instruction {ins!r}")


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def _read_arguments(path):
    with open(path, "r", encoding="utf-8") as fh:
        tokens = [line.rstrip("\n") for line in fh if line != "\n"]
    return [_literal(token) for token in tokens]


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(
            "usage: target_runner.py <target-file> <arguments-file>\n")
        return 2
    try:
        with open(argv[1], "r", encoding="utf-8") as fh:
            text = fh.read()
        arguments = _read_arguments(argv[2])
    except OSError as exc:
        _fail(f"cannot read inputs: {exc}")

    programs = _parse(text)
    main_fn = programs["main"]
    if len(arguments) != len(main_fn["params"]):
        _fail(f"main expects {len(main_fn['params'])} argument(s), got "
              f"{len(arguments)}")
    for param, arg in zip(main_fn["params"], arguments):
        pname, ptype, _vid_ = param
        if ptype == "int" and (not isinstance(arg, int)
                               or isinstance(arg, bool)):
            _fail(f"argument {pname!r}: expected int, got {arg!r}")
        if ptype == "bool" and not isinstance(arg, bool):
            _fail(f"argument {pname!r}: expected bool, got {arg!r}")

    return _Engine(programs).invoke_main(arguments)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

